                }
                return Err(format!("argument {name}: ignored explicit argument {}", quote(&exp)));
            }
            if takes {
                let mut j = start + 1;
                while j < n && matches!(self.kinds[j], Kind::Marker) {
                    j += 1;
                }
                if j >= n || !matches!(self.kinds[j], Kind::Positional) {
                    return Err(format!("argument {name}: expected one argument"));
                }
                j += 1;
                while j < n && matches!(self.kinds[j], Kind::Marker) {
                    j += 1;
                }
                let value = without_marker(&self.slice(start + 1, j))[0].to_vec();
                tuples.push((act, Some(value)));
                stop = j;
            } else {
                tuples.push((act, None));
                stop = start + 1;
            }
            break;
        }
        for (act, value) in tuples {
            match act {
                Act::Help => return Ok(Step::Help),
                Act::Json => self.opts.json = true,
                Act::Min | Act::Max => {
                    let flag = if act == Act::Min { "--min-level" } else { "--max-level" };
                    let level = level_of(flag, &value.unwrap_or_default())?;
                    if act == Act::Min {
                        self.opts.min_level = level;
                    } else {
                        self.opts.max_level = level;
                    }
                }
            }
        }
        Ok(Step::Next(stop))
    }
}

fn quote(bytes: &[u8]) -> String {
    format!("'{}'", String::from_utf8_lossy(bytes))
}

/// `type=int, choices=range(1, 7)`
fn level_of(flag: &str, value: &[u8]) -> Result<u8, String> {
    let parsed = std::str::from_utf8(value).ok().and_then(pystr::py_int);
    match parsed {
        None => Err(format!("argument {flag}: invalid int value: {}", quote(value))),
        Some(v @ 1..=6) => Ok(v as u8),
        Some(v) => Err(format!("argument {flag}: invalid choice: {v} (choose from 1, 2, 3, 4, 5, 6)")),
    }
}

fn parse_inner(args: &[Vec<u8>]) -> Result<Parsed, String> {
    let mut kinds = Vec::with_capacity(args.len());
    let mut after_marker = false;
    for arg in args {
        kinds.push(if after_marker {
            Kind::Positional
        } else if arg == b"--" {
            after_marker = true;
            Kind::Marker
        } else {
            parse_optional(arg)
        });
    }
    let n = args.len();
    let mut p = Parser {
        args,
        kinds,
        opts: Options { file: b"-".to_vec(), min_level: 1, max_level: 6, json: false },
        file_done: false,
    };
    let mut extras = false;
    let mut start = 0;
    if let Some(max_opt) = (0..n).rev().find(|&i| is_opt(&p.kinds[i])) {
        while start <= max_opt {
            let next = (start..n).find(|&i| is_opt(&p.kinds[i])).unwrap_or(max_opt);
            if start != next {
                let end = p.consume_positionals(start);
                if end > start {
                    start = end;
                    continue;
                }
                start = end;
            }
            if !is_opt(&p.kinds[start]) {
                extras = true;
                start = next;
            }
            if matches!(p.kinds[start], Kind::Unknown) {
                extras = true;
                start += 1;
                continue;
            }
            match p.consume_optional(start)? {
                Step::Help => return Ok(Parsed::Help),
                Step::Next(stop) => start = stop,
            }
        }
    }
    if p.consume_positionals(start) < n {
        extras = true;
    }
    if extras {
        return Err("unrecognized arguments".to_string());
    }
    if p.opts.min_level > p.opts.max_level {
        return Err("--min-level must not be greater than --max-level".to_string());
    }
    Ok(Parsed::Run(p.opts))
}

pub fn parse(args: &[Vec<u8>]) -> Parsed {
    parse_inner(args).unwrap_or_else(Parsed::Usage)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn run(args: &[&str]) -> Result<Option<(Vec<u8>, u8, u8, bool)>, String> {
        let args: Vec<Vec<u8>> = args.iter().map(|a| a.as_bytes().to_vec()).collect();
        match parse_inner(&args)? {
            Parsed::Run(o) => Ok(Some((o.file, o.min_level, o.max_level, o.json))),
            _ => Ok(None),
        }
    }

    fn ok(args: &[&str]) -> (String, u8, u8, bool) {
        let (f, a, b, c) = run(args).unwrap().unwrap();
        (String::from_utf8(f).unwrap(), a, b, c)
    }

    #[test]
    fn defaults_and_last_wins() {
        assert_eq!(ok(&[]), ("-".into(), 1, 6, false));
        assert_eq!(ok(&["a.md", "--json", "--min-level=2", "--min-level", "3"]), ("a.md".into(), 3, 6, true));
        assert_eq!(ok(&["--max-level", "1", "--max-level", "4", "f"]), ("f".into(), 1, 4, false));
        assert_eq!(ok(&["--", "--json"]), ("--json".into(), 1, 6, false));
        assert_eq!(ok(&["-5", "--min-level", "٣"]), ("-5".into(), 3, 6, false));
    }

    #[test]
    fn usage_errors() {
        for bad in [
            &["--js"][..],
            &["--min", "2"],
            &["--json=1"],
            &["a", "b"],
            &["a", "--json", "b"],
            &["--min-level"],
            &["--min-level", "--json"],
            &["--min-level", "0"],
            &["--min-level", "4", "--max-level", "2"],
            &["--bogus"],
            &["-hx"],
            &["--min-level", "9", "-h"],
            &["-a", "b"],
        ] {
            assert!(run(bad).is_err(), "{bad:?}");
        }
    }

    #[test]
    fn help_wins_in_order() {
        for good in [&["-h"][..], &["--bogus", "-h"], &["-h", "--min-level", "9"], &["-hh"], &["--help"]] {
            assert!(run(good).unwrap().is_none(), "{good:?}");
        }
    }
}

